/* =====================================================
   SMART WATER CONTROL CENTER - PREMIUM SCADA
   ===================================================== */

.sw-panel,
.sw-panel * {
  box-sizing: border-box;
}

.sw-panel {
  --bg: #091321;
  --surface: #112235;
  --border: #294b63;
  --cyan: #3bd7ee;
  --cyan-light: #91eff8;
  --green: #49dfb0;
  --muted: #89a9c2;
  --white: #eff7ff;

  position: relative;
  width: 100%;
  padding: 25px;
  overflow: hidden;
  border: 1px solid #203c52;
  border-radius: 17px;
  background:
    radial-gradient(ellipse at 50% 45%,
      rgba(23, 90, 119, .15), transparent 58%),
    linear-gradient(145deg, #0c1928, #08111e 80%);
  color: var(--white);
  font-family: Arial, Helvetica, sans-serif;
}

/* Technical background grid */
.sw-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .12;
  background-image:
    linear-gradient(rgba(80, 148, 180, .15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(80, 148, 180, .15) 1px, transparent 1px);
  background-size: 28px 28px;
}

/* HEADER */
.sw-header {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
  padding-bottom: 20px;
  border-bottom: 1px solid rgba(91, 150, 183, .22);
}

.sw-eyebrow {
  color: var(--cyan);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  line-height: 1.6;
}

.sw-header h2 {
  margin: 7px 0 0;
  color: var(--white);
  font-size: clamp(22px, 2.5vw, 30px);
  font-weight: 700;
  letter-spacing: -.6px;
}

.sw-subtitle {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: .25px;
}

.sw-status {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 11px 14px;
  border: 1px solid rgba(73, 223, 176, .3);
  border-radius: 30px;
  background: rgba(25, 88, 73, .15);
  color: var(--green);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  white-space: nowrap;
}

.sw-status span {
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px rgba(73, 223, 176, .45);
}

/* NETWORK */
.sw-network {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 450px;
  min-width: 0;
  margin: 25px 0 18px;
}

.sw-pipes {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.pipe-base {
  fill: none;
  stroke: #203d53;
  stroke-width: 10;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.pipe-flow {
  fill: none;
  stroke: var(--cyan);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 10 10;
  animation: sw-water-flow 1.7s linear infinite;
  filter: drop-shadow(0 0 3px rgba(59, 215, 238, .35));
}

.sw-node {
  fill: #10283b;
  stroke: var(--cyan);
  stroke-width: 2.5;
}

.sw-junction {
  stroke-width: 3;
}

/* SOURCE: separate label from the pipe */
.sw-source {
  position: absolute;
  left: 0;
  top: 50%;
  width: 23%;
  min-width: 0;
  transform: translateY(-50%);
  text-align: center;
  z-index: 2;
}

.sw-source-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  margin: 0 auto 12px;
  border: 1px solid rgba(59, 215, 238, .3);
  border-radius: 17px;
  background: linear-gradient(145deg, #163247, #0d2030);
  color: var(--cyan);
  box-shadow: 0 8px 24px rgba(0, 0, 0, .15);
}

.sw-source-icon svg {
  display: block;
  width: 43px;
  height: 43px;
}

.sw-source-label {
  display: inline-block;
  padding: 5px 7px;
  border-radius: 5px;
  background: #0b1827;
  color: var(--white);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .65px;
  white-space: nowrap;
}

.sw-source-caption {
  margin-top: 9px;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 1px;
}

.sw-source-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 12px;
  padding: 5px 7px;
  border: 1px solid rgba(59, 215, 238, .18);
  border-radius: 5px;
  color: #7fc6d9;
  font-size: 8px;
  letter-spacing: .5px;
  white-space: nowrap;
}

.sw-source-tag span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--cyan);
}

/* BIGGER ZONE CARDS */
.sw-zone {
  position: absolute;
  left: 52%;
  width: 46%;
  height: 132px;
  padding: 13px 15px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: linear-gradient(120deg, #14283b, #0f2032);
  box-shadow:
    0 9px 22px rgba(0, 0, 0, .17),
    inset 0 1px 0 rgba(255, 255, 255, .025);
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 8px;
}

.sw-zone::before {
  content: "";
  position: absolute;
  top: 0;
  left: 15px;
  width: 50px;
  height: 2px;
  background: var(--cyan);
}

/* Three evenly spaced branches */
.sw-zone.farm {
  top: 0;
}

.sw-zone.home {
  top: 34%;
}

.sw-zone.industry {
  top: 68%;
}

/* Heading and zone identity */
.sw-zone-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  min-height: 43px;
}

.sw-zone-heading {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.sw-zone-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border: 1px solid rgba(59, 215, 238, .23);
  border-radius: 10px;
  background: rgba(59, 215, 238, .06);
}

.sw-zone-icon svg {
  width: 32px;
  height: 32px;
  display: block;
}

.sw-zone h3 {
  margin: 0;
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

.sw-zone-heading p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 8px;
  line-height: 1.4;
  letter-spacing: .65px;
}

/* Mode badge */
.sw-mode {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 52px;
  padding: 8px 9px;
  border: 1px solid rgba(73, 223, 176, .2);
  border-radius: 7px;
  background: rgba(38, 119, 93, .19);
  color: var(--green);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .7px;
  white-space: nowrap;
}

/* Zone-specific miniature illustrations */
.sw-zone-art {
  height: 31px;
  min-height: 31px;
  padding-left: 4px;
  overflow: hidden;
  opacity: .95;
}

.sw-zone-art svg {
  display: block;
  width: 100%;
  max-width: 170px;
  height: 31px;
}

/* Valve row */
.sw-zone-bottom {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  margin-top: auto;
  padding-top: 7px;
  border-top: 1px solid rgba(91, 150, 183, .16);
  color: #9bb7cc;
  font-size: 10px;
  line-height: 1.3;
}

.sw-valve {
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 2px;
  background: var(--green);
  box-shadow: 0 0 8px rgba(73, 223, 176, .25);
}

.sw-zone-bottom b {
  margin-left: auto;
  color: var(--green);
  font-size: 9px;
}

/* FOOTER */
.sw-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 12px;
  padding-top: 16px;
  border-top: 1px solid rgba(91, 150, 183, .22);
  color: var(--muted);
  font-size: 10px;
  letter-spacing: .5px;
}

.sw-legend {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.sw-legend i {
  display: inline-block;
  width: 17px;
  height: 3px;
  border-radius: 2px;
  background: var(--cyan);
  box-shadow: 0 0 7px rgba(59, 215, 238, .35);
}

.sw-footer-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sw-footer-meta b {
  color: var(--cyan);
}

.sw-footer-meta span {
  color: #42667e;
}

/* FLOW ANIMATION */
@keyframes sw-water-flow {
  from { stroke-dashoffset: 0; }
  to { stroke-dashoffset: -40; }
}

/* RESPONSIVE */
@media (max-width: 600px) {
  .sw-panel {
    padding: 14px;
    border-radius: 12px;
  }

  .sw-header {
    gap: 12px;
  }

  .sw-eyebrow {
    font-size: 8px;
    letter-spacing: 1px;
  }

  .sw-header h2 {
    font-size: 21px;
  }

  .sw-subtitle {
    font-size: 10px;
  }

  .sw-status {
    padding: 8px 10px;
    font-size: 8px;
  }

  .sw-network {
    height: 390px;
    margin-top: 20px;
  }

  .sw-source {
    width: 25%;
  }

  .sw-source-icon {
    width: 45px;
    height: 45px;
    margin-bottom: 8px;
  }

  .sw-source-icon svg {
    width: 32px;
    height: 32px;
  }

  .sw-source-label {
    font-size: 8px;
    letter-spacing: 0;
  }

  .sw-source-caption {
    font-size: 8px;
  }

  .sw-source-tag {
    font-size: 6px;
    padding: 4px;
  }

  .sw-zone {
    left: 47%;
    width: 52%;
    height: 116px;
    padding: 10px;
    gap: 6px;
  }

  .sw-zone.farm { top: 0; }
  .sw-zone.home { top: 34%; }
  .sw-zone.industry { top: 68%; }

  .sw-zone-icon {
    width: 33px;
    height: 33px;
  }

  .sw-zone-icon svg {
    width: 26px;
    height: 26px;
  }

  .sw-zone-heading {
    gap: 7px;
  }

  .sw-zone h3 {
    font-size: 10px;
  }

  .sw-zone-heading p {
    font-size: 7px;
    letter-spacing: 0;
  }

  .sw-mode {
    min-width: 40px;
    padding: 6px;
    font-size: 8px;
  }

  .sw-zone-art {
    height: 25px;
    min-height: 25px;
  }

  .sw-zone-art svg {
    height: 25px;
  }

  .sw-zone-bottom {
    font-size: 9px;
  }

  .sw-footer {
    font-size: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pipe-flow {
    animation: none;
  }
}


/* Live monitoring additions */
.sw-network {
  height: 610px;
}

.sw-zone {
  height: 188px;
}

.sw-zone.farm { top: 0; }
.sw-zone.home { top: 34%; }
.sw-zone.industry { top: 68%; }

.sw-live-metrics {
  position: relative;
  z-index: 1;
  width: 100%;
  min-width: 0;
}

.sw-live-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px 9px;
  font-size: 9px;
  line-height: 1.25;
}

.sw-live-grid > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px;
  min-width: 0;
  color: var(--muted);
}

.sw-live-grid span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sw-live-grid b {
  color: var(--white);
  font-size: 10px;
  white-space: nowrap;
}

.sw-live-connection {
  margin-top: 5px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1px;
}

.sw-live-connection.is-online {
  color: var(--green);
}

.sw-live-connection.is-offline {
  color: #ff7777;
}

.sw-zone.sw-unavailable {
  border-color: #8b5960;
}

.sw-zone.sw-unavailable .sw-zone-art {
  opacity: .35;
}

.sw-zone.sw-sensor-fault {
  border-color: #ff5c65;
  box-shadow: 0 0 12px rgba(255, 92, 101, .18);
}

.sw-status.sw-network-offline {
  border-color: rgba(255, 92, 101, .55);
  color: #ff7777;
}

.sw-status.sw-network-offline span {
  background: #ff5c65;
  box-shadow: 0 0 10px rgba(255, 92, 101, .45);
}

.sw-live-summary {
  color: var(--muted);
  font-size: 9px;
}

@media (max-width: 600px) {
  .sw-network {
    height: 550px;
  }

  .sw-zone {
    height: 170px;
    padding: 9px;
  }

  .sw-zone.farm { top: 0; }
  .sw-zone.home { top: 34%; }
  .sw-zone.industry { top: 68%; }

  .sw-live-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 4px 6px;
    font-size: 8px;
  }

  .sw-live-grid b {
    font-size: 9px;
  }

  .sw-live-summary {
    font-size: 7px;
  }
}


