/* Final card spacing */
.sw-zone {
  height: 195px;
  padding: 12px 14px;
  gap: 7px;
  border-radius: 16px;
}

.sw-live-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 12px;
  row-gap: 10px;
}

.sw-live-grid > div {
  min-width: 0;
  justify-content: space-between;
  gap: 5px;
}

.sw-live-grid span {
  font-size: 10px;
}

.sw-live-grid b {
  font-size: 11px;
}

.sw-live-connection {
  margin-top: 5px;
}

.sw-zone-bottom {
  margin-top: auto;
  padding-top: 7px;
  flex-shrink: 0;
  border-top: 1px solid rgba(130, 180, 210, .12);
}

.sw-mode {
  min-width: 65px;
  padding: 6px 10px;
  border-radius: 9px;
  font-size: 10px;
  font-weight: 800;
}

.sw-mode.is-manual {
  color: #ffca72;
  border-color: rgba(255, 202, 114, .45);
  background: rgba(255, 202, 114, .12);
}

.sw-mode.is-offline {
  color: #ff7777;
  border-color: rgba(255, 92, 101, .45);
  background: rgba(255, 92, 101, .1);
}


/* Move zone illustrations to the right */
.sw-zone {
  position: absolute;
}

.sw-zone-art {
  position: absolute;
  right: 14px;
  bottom: 36px;
  width: 105px;
  height: 30px;
  min-height: 30px;
  margin: 0;
  opacity: .8;
  pointer-events: none;
}

.sw-zone-art svg {
  width: 100%;
  height: 100%;
  display: block;
}

.sw-live-metrics {
  position: relative;
  z-index: 2;
  padding-right: 0;
}

.sw-zone-bottom {
  position: relative;
  z-index: 2;
}

@media (max-width: 600px) {
  .sw-zone-art {
    right: 10px;
    bottom: 36px;
    width: 75px;
    height: 24px;
  }
}

settings.js:
var root = container.querySelector('.sw-panel');
if (!root) return;

var zoneDefs = [
  { name: 'Farm Zone', selector: '.sw-zone.farm' },
  { name: 'Residential Zone', selector: '.sw-zone.home' },
  { name: 'Industrial Zone', selector: '.sw-zone.industry' }
];

var keys = [
  'level', 'flow', 'temp', 'rain', 'mode',
  'isClosed', 'valveAngle', 'closedCount',
  'alarmCount', 'activeAlarms', 'demand',
  'targetFlow', 'sensorFault'
];

var latest = {};
var subscriptionId = null;
var timer = null;
var destroyed = false;

function findAliasId() {
  var aliases = ctx.aliasController.getEntityAliases();
  if (!aliases) return null;

  if (Array.isArray(aliases)) {
    for (var i = 0; i < aliases.length; i++) {
      var item = aliases[i];
      if (item && (item.alias === 'Water Zones' ||
                   item.name === 'Water Zones')) {
        return item.id || item.entityAliasId || null;
      }
    }
    return null;
  }

  var ids = Object.keys(aliases);

  for (var j = 0; j < ids.length; j++) {
    var alias = aliases[ids[j]];
    if (alias && (alias.alias === 'Water Zones' ||
                  alias.name === 'Water Zones')) {
      return ids[j];
    }
  }

  return null;
}

function valueOf(data, key) {
  return data && data[key] ? data[key].value : null;
}

function display(value, unit) {
  if (value === null || value === undefined || value === '') {
    return '—';
  }
  return String(value) + (unit || '');
}

function truthy(value) {
  return value === true || value === 1 ||
    value === 'true' || value === '1';
}

function getZoneData(name) {
  return latest[name] || {};
}

function ensureMetrics(card) {
  var panel = card.querySelector('.sw-live-metrics');

  if (panel) return panel;

  panel = document.createElement('div');
  panel.className = 'sw-live-metrics';

  panel.innerHTML =
    '<div class="sw-live-grid">' +
      '<div><span>Water level</span><b data-k="level">—</b></div>' +
      '<div><span>Flow rate</span><b data-k="flow">—</b></div>' +
      '<div><span>Rain</span><b data-k="rain">—</b></div>' +
      '<div><span>Demand</span><b data-k="demand">—</b></div>' +
      '<div><span>Target flow</span><b data-k="targetFlow">—</b></div>' +
      '<div><span>Valve angle</span><b data-k="valveAngle">—</b></div>' +
      '<div><span>Temperature</span><b data-k="temp">—</b></div>' +
    '</div>' +
    '<div class="sw-live-connection">WAITING FOR DATA</div>';

  var art = card.querySelector('.sw-zone-art');
  if (art) {
    card.insertBefore(panel, art);
  } else {
    card.appendChild(panel);
  }

  return panel;
}

function render() {
  var closedCount = 0;
  var alarmCount = 0;
  var onlineCount = 0;

  zoneDefs.forEach(function (zone) {
    var card = root.querySelector(zone.selector);
    if (!card) return;

    var data = getZoneData(zone.name);
    var metrics = ensureMetrics(card);

    var lastTs = 0;
    Object.keys(data).forEach(function (key) {
      if (data[key].timestamp > lastTs) {
        lastTs = data[key].timestamp;
      }
    });

    var online = lastTs > 0 && Date.now() - lastTs <= 300000;

    if (online) onlineCount++;

    var fields = {
      level: display(valueOf(data, 'level'), '%'),
      flow: display(valueOf(data, 'flow'), '%'),
      rain: display(valueOf(data, 'rain')),
      demand: display(valueOf(data, 'demand'), '%'),
      targetFlow: display(valueOf(data, 'targetFlow'), '%'),
      valveAngle: display(valueOf(data, 'valveAngle'), '°'),
      temp: display(valueOf(data, 'temp'), ' °C')
    };

    Object.keys(fields).forEach(function (key) {
      var el = metrics.querySelector('[data-k="' + key + '"]');
      if (el) el.textContent = online ? fields[key] : '—';
    });

    var connection = metrics.querySelector('.sw-live-connection');
    connection.textContent = online ? 'ONLINE' : 'UNAVAILABLE';
    connection.classList.toggle('is-online', online);
    connection.classList.toggle('is-offline', !online);
    card.classList.toggle('sw-unavailable', !online);


    var modeEl = card.querySelector('.sw-mode');

    if (modeEl) {
      var mode = String(valueOf(data, 'mode') || '')
        .trim()
        .toUpperCase();

      if (!online) {
        modeEl.textContent = 'OFFLINE';
        modeEl.classList.remove('is-manual');
        modeEl.classList.add('is-offline');
      } else {
        modeEl.textContent =
          mode === 'MANUAL' ? 'MANUAL' :
          mode === 'AUTO' ? 'AUTO' :
          mode || 'UNKNOWN';

        modeEl.classList.remove('is-offline');
        modeEl.classList.toggle('is-manual', mode === 'MANUAL');
      }
    }


    var closed = truthy(valueOf(data, 'isClosed'));
    if (online && closed) closedCount++;

    var alarms = Number(valueOf(data, 'alarmCount'));
    if (online && Number.isFinite(alarms)) {
      alarmCount += alarms;
    }

    var fault = truthy(valueOf(data, 'sensorFault'));
    card.classList.toggle('sw-sensor-fault', online && fault);

    var valve = card.querySelector('.sw-valve');
    if (valve) {
      valve.style.background = !online
        ? '#718096'
        : (closed || fault ? '#ff5c65' : '#49dfb0');
    }

    var dot = card.querySelector('.sw-zone-bottom b');
    if (dot) {
      dot.style.color = !online
        ? '#718096'
        : (closed || fault ? '#ff5c65' : '#49dfb0');
    }
  });

  var status = root.querySelector('.sw-status');
  if (status) {
    var textNode = status.lastChild;
    if (textNode && textNode.nodeType === 3) {
      textNode.textContent = onlineCount === 3
        ? ' NETWORK ONLINE'
        : ' ' + onlineCount + '/3 ZONES ONLINE';
    }
    status.classList.toggle('sw-network-offline', onlineCount === 0);
  }

  var footer = root.querySelector('.sw-footer-meta');
  if (footer) {
    var summary = footer.querySelector('.sw-live-summary');

    if (!summary) {
      summary = document.createElement('span');
      summary.className = 'sw-live-summary';
      footer.appendChild(summary);
    }

    summary.textContent =
      ' / CLOSED: ' + closedCount +
      ' / ACTIVE ALARMS: ' + alarmCount;
  }
}

function acceptSubscriptionData(subscription) {
  var rows = subscription && subscription.data
    ? subscription.data : [];

  rows.forEach(function (row) {
    var ds = row.datasource || {};
    var name = ds.entityName || ds.entityLabel ||
      (ds.entity && ds.entity.name);

    var key = row.dataKey && row.dataKey.name;
    var points = row.data || [];

    if (!name || !key || !points.length) return;

    var point = points[points.length - 1];
    if (!point || point.length < 2) return;

    if (!latest[name]) latest[name] = {};

    latest[name][key] = {
      value: point[1],
      timestamp: Number(point[0]) || 0
    };
  });

  render();
}

function startSubscription() {
  var aliasId = findAliasId();

  if (!aliasId) {
    console.error('Water Zones alias was not found.');
    var status = root.querySelector('.sw-status');
    if (status) {
      status.lastChild.textContent = ' ALIAS NOT FOUND';
    }
    return;
  }

  var options = {
    type: 'latest',
    datasources: [{
      type: 'entity',
      entityAliasId: aliasId,
      dataKeys: keys.map(function (key) {
        return {
          name: key,
          type: 'timeseries',
          label: key,
          settings: {}
        };
      })
    }],
    callbacks: {
      onDataUpdated: function (subscription) {
        acceptSubscriptionData(subscription);
      },
      onDataUpdateError: function (subscription, error) {
        console.error('Water Zones subscription error:', error);
      }
    }
  };

  ctx.subscriptionApi.createSubscription(options, true).subscribe(
    function (subscription) {
      subscriptionId = subscription.id;
      acceptSubscriptionData(subscription);
    },
    function (error) {
      console.error('Could not create Water Zones subscription:', error);
    }
  );
}

startSubscription();

timer = setInterval(render, 5000);

ctx.registerDestroyCallback(function () {
  destroyed = true;

  if (timer) clearInterval(timer);

  if (subscriptionId !== null) {
    ctx.subscriptionApi.removeSubscription(subscriptionId);
  }
});

